// Bronze = dado cru: precos entram como texto ("R$ 400"); a Silver parseia.
// Normalizacao minima: extrair o codigo MLB do link (o id do item).
//
// categoria (25/09/2026): o ML trocou o layout e o titulo do carrossel
// passou a vir em espanhol e DESALINHADO do conteudo. Desde a receita v4 a categoria vem do
// link "Ver mais" de cada carrossel (href com o codigo MLB da categoria), nos dois layouts.
// O nome sai do MAPA abaixo, conferido nos HTML de 29/07 e 24/09 (mesmo id, mesmo nome, mesma
// ordem): categoria_pagina continua com os mesmos 10 nomes da serie, e o id cru vai para
// categoria_id. Id fora do mapa grava o proprio id como nome (a Silver avisa carrossel
// desconhecido). Valor que nao e link (receita v3, layout antigo) passa como veio.
//
// rank (24/09/2026): a POSICAO no carrossel, no formato "k de M" que a
// fonte declara no aria-label de cada slide. A receita nao alcanca esse atributo (ele mora
// no proprio slide), entao a posicao e NUMERADA AQUI, na ordem em que o enxame-api devolve as
// linhas - a ordem do DOM, igual ao aria-label nos 3 HTML versionados (537 de 537 slides).
// Decisao: numerar no n8n, sem recriar o container. k conta dentro do carrossel;
// M e o total do carrossel na resposta. Linha sem categoria, ou de carrossel partido em mais
// de um bloco, fica SEM rank.
//
// selo_mais_vendido: ate 25/09 o texto "N MAIS VENDIDO" (rank declarado, com buracos); no
// layout novo o rotulo do slide SEM numero ("MAIS VENDIDO", "OFERTA IMPERDIVEL"...).
// Guardado cru; nao alimenta o percentil.
const MAPA = {
  MLB1144: 'Games',
  MLB5726: 'Eletrodomésticos',
  MLB263532: 'Ferramentas',
  MLB1246: 'Beleza e Cuidado Pessoal',
  MLB1051: 'Celulares e Telefones',
  MLB1648: 'Informática',
  MLB1000: 'Eletrônicos, Áudio e Vídeo',
  MLB1276: 'Esportes e Fitness',
  MLB1430: 'Calçados, Roupas e Bolsas',
  MLB5672: 'Acessórios para Veículos'
};
const LINK_CATEGORIA = new RegExp('/mais-vendidos/(MLB[0-9]+)');
const resp = $input.first().json;
const linhas = resp.linhas || [];
const agora = new Date().toISOString();
const cats = linhas.map(n => {
  const bruto = n.categoria || null;
  if (!bruto) return { nome: null, id: null };
  const m = String(bruto).match(LINK_CATEGORIA);
  if (!m) return { nome: bruto, id: null };
  return { nome: MAPA[m[1]] || m[1], id: m[1] };
});
const total = {};
const blocos = {};
let anterior = null;
cats.forEach(k => {
  const c = k.nome;
  if (c) {
    total[c] = (total[c] || 0) + 1;
    if (c !== anterior) { blocos[c] = (blocos[c] || 0) + 1; }
  }
  anterior = c;
});
const visto = {};
return linhas.map((n, i) => {
  const link = n.link || '';
  const m = link.match(/MLB-?[0-9]+/i);
  const c = cats[i].nome;
  let rank = null;
  if (c && blocos[c] === 1) {
    visto[c] = (visto[c] || 0) + 1;
    rank = visto[c] + ' de ' + total[c];
  }
  return { json: {
    item_id: m ? m[0].replace('-', '') : null,
    titulo: n.titulo || null,
    preco: n.preco || null,
    preco_antigo: n.preco_antigo || null,
    desconto: n.desconto || null,
    link: link || null,
    categoria_pagina: c,
    categoria_id: cats[i].id,
    rank: rank,
    selo_mais_vendido: n.selo_mais_vendido || null,
    coletado_em: agora
  }};
});
